from z3 import *

def solve():
    n = 14
    E = [[Bool(f"e_{i}_{j}") if i < j else None for j in range(n)] for i in range(n)]

    def edge(i, j):
        if i < j: return E[i][j]
        if i > j: return E[j][i]
        return False

    s = Solver()

    # Degree >= 5
    for i in range(n):
        s.add(Sum([If(edge(i, j), 1, 0) for j in range(n) if i != j]) >= 5)

    # No clique of size 4
    for i in range(n):
        for j in range(i+1, n):
            for k in range(j+1, n):
                for l in range(k+1, n):
                    s.add(Not(And(edge(i, j), edge(i, k), edge(i, l), edge(j, k), edge(j, l), edge(k, l))))

    # Chromatic number <= 5
    # We can assign a color from 0 to 4 to each vertex
    C = [Int(f"c_{i}") for i in range(n)]
    for i in range(n):
        s.add(C[i] >= 0, C[i] <= 4)

    for i in range(n):
        for j in range(i+1, n):
            s.add(Implies(edge(i, j), C[i] != C[j]))

    if s.check() == sat:
        m = s.model()
        edges = []
        for i in range(n):
            for j in range(i+1, n):
                if is_true(m[E[i][j]]):
                    edges.append((i, j))
        print("SAT")
        print(edges)
    else:
        print("UNSAT")

solve()

